interface GenericButtonProps {
    text?: string;
    className?: string;
    onClick?: (e: any) => void;
    children?: React.ReactNode;
}

const GenericButton = (props: GenericButtonProps) => {
    return (
        <button onClick={props.onClick} className={`${props.className} bg-white font-medium generic-button px-3 py-2.5 text-[14px] rounded-md outline-1 outline-[#D9D9D9] items-center justify-center font-[Outfit] cursor-pointer hover:bg-gray-50 active:bg-gray-100 transition-all `}>
            {props.text}
            {props.children}
        </button>
    )
}

export default GenericButton;

